package com.gathin.tvhome;

import android.content.Context;
import android.os.StatFs;
import android.text.format.Formatter;
import android.util.Log;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;

/** Local-only screensaver photo collection, populated from Picsum, Bing, and Unsplash. */
final class PhotoStore {
    static final int JOB_ID=78231, PICSUM_JOB_ID=78232, BING_JOB_ID=78233, UNSPLASH_JOB_ID=78234;
    static final int PICSUM_NOW_JOB_ID=78332, BING_NOW_JOB_ID=78333, UNSPLASH_NOW_JOB_ID=78334;
    static final String MANIFEST="photo_manifest.json";
    static final String SOURCE_BING="bing", SOURCE_PICSUM="picsum", SOURCE_UNSPLASH="unsplash", SOURCE_BOTH="all";
    private static final Object MANIFEST_LOCK=new Object();
    private static final long MB=1024L*1024L, MIN_FREE=2L*1024L*MB, DEFAULT_CAP=200L*MB, FILE_CAP=1536*1024L;
    static final class Photo {
        final String file,id,author,source,title,copyright,startdate,downloadLocation;
        final boolean tracked;
        Photo(String f,String i,String a,String s,String t,String c,String d){this(f,i,a,s,t,c,d,"",false);}
        Photo(String f,String i,String a,String s,String t,String c,String d,String location,boolean tracked){file=f;id=i;author=a;source=s;title=t;copyright=c;startdate=d;downloadLocation=location;this.tracked=tracked;}
    }
    private PhotoStore(){}
    static void recordError(Context c,Exception e){String error=e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage());c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).edit().putString("photo_last_error",error).putLong("photo_last_error_at",System.currentTimeMillis()).apply();}
    static void scheduleIfMissingThrottled(Context c){if(!c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).getBoolean("dream_photos",true)||!list(c,chosenSource(c)).isEmpty())return;android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);long now=System.currentTimeMillis();if(now-p.getLong("photo_empty_refresh_at",0)<60L*60*1000)return;p.edit().putLong("photo_empty_refresh_at",now).apply();schedule(c,true);}
    static File dir(Context c){File f=new File(c.getFilesDir(),"photos");if(!f.exists())f.mkdirs();return f;}
    static long cap(Context c){int mb=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).getInt("photo_storage_mb",200);return (mb==100||mb==200||mb==500?mb*MB:DEFAULT_CAP);}
    static String chosenSource(Context c){android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);String stored=p.getString("photo_sources",null);if(stored==null){String legacy=p.getString("photo_source","both");Set<String> migrated=PhotoSources.parse(legacy);stored=PhotoSources.serialize(migrated);p.edit().putString("photo_sources",stored).apply();}Set<String> sources=PhotoSources.parse(stored);return PhotoSources.serialize(sources);}
    static Set<String> selectedSources(Context c){return PhotoSources.parse(chosenSource(c));}
    static List<Photo> list(Context c){ArrayList<Photo> out=new ArrayList<>();try{JSONArray a=new JSONObject(readText(new File(c.getFilesDir(),MANIFEST))).optJSONArray("photos");if(a!=null)for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String name=o.optString("file"),src=o.optString("source",SOURCE_PICSUM);File f=new File(dir(c),name);if(name.matches("[A-Za-z0-9_-]+\\.jpg")&&f.isFile()&&f.length()>0)out.add(new Photo(name,o.optString("id"),o.optString("author"),src,o.optString("title"),o.optString("copyright"),o.optString("startdate"),o.optString("download_location"),o.optBoolean("tracked",false)));}}catch(Exception e){if(new File(c.getFilesDir(),MANIFEST).exists()){recordError(c,e);Log.e("TvHomePhotos","manifest read failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}}return out;}
    static List<Photo> list(Context c,String selected){return list(c,PhotoSources.parse(selected));}
    static List<Photo> list(Context c,Set<String> selected){ArrayList<Photo> bing=new ArrayList<>(),unsplash=new ArrayList<>(),picsum=new ArrayList<>();for(Photo p:list(c))if(selected.contains(p.source)){if(SOURCE_BING.equals(p.source))bing.add(p);else if(SOURCE_UNSPLASH.equals(p.source))unsplash.add(p);else if(SOURCE_PICSUM.equals(p.source))picsum.add(p);}bing.sort((a,b)->b.startdate.compareTo(a.startdate));Comparator<Photo> newest=(a,b)->Long.compare(new File(dir(c),b.file).lastModified(),new File(dir(c),a.file).lastModified());unsplash.sort(newest);picsum.sort(newest);ArrayList<Photo> out=new ArrayList<>(bing);for(int i=0;i<Math.max(unsplash.size(),picsum.size());i++){if(i<unsplash.size())out.add(unsplash.get(i));if(i<picsum.size())out.add(picsum.get(i));}return out;}
    static long size(Context c,String selected){long n=0;for(Photo p:list(c,selected))n+=new File(dir(c),p.file).length();return n;}
    static String summary(Context c){List<Photo> photos=list(c);long n=0;int bing=0,picsum=0,unsplash=0;for(Photo p:photos){n+=new File(dir(c),p.file).length();if(SOURCE_BING.equals(p.source))bing++;else if(SOURCE_PICSUM.equals(p.source))picsum++;else if(SOURCE_UNSPLASH.equals(p.source))unsplash++;}return c.getString(R.string.photo_count_size,photos.size(),Formatter.formatFileSize(c,n),Formatter.formatFileSize(c,cap(c)))+" (Bing "+bing+", Unsplash "+unsplash+", Picsum "+picsum+")";}
    static boolean hasPhotos(Context c){return !list(c,chosenSource(c)).isEmpty();}
    static void schedule(Context c,boolean now){android.app.job.JobScheduler js=(android.app.job.JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(js==null)return;android.content.ComponentName cn=new android.content.ComponentName(c,PhotoDownloadJob.class);Set<String> sources=selectedSources(c);if(sources.contains(SOURCE_PICSUM))schedulePeriodic(js,cn,PICSUM_JOB_ID,7L*24*60*60*1000);else js.cancel(PICSUM_JOB_ID);if(sources.contains(SOURCE_BING))schedulePeriodic(js,cn,BING_JOB_ID,24L*60*60*1000);else js.cancel(BING_JOB_ID);if(sources.contains(SOURCE_UNSPLASH))schedulePeriodic(js,cn,UNSPLASH_JOB_ID,12L*60*60*1000);else js.cancel(UNSPLASH_JOB_ID);if(sources.contains(SOURCE_PICSUM)){if(now)scheduleNow(js,cn,PICSUM_NOW_JOB_ID);}else js.cancel(PICSUM_NOW_JOB_ID);if(sources.contains(SOURCE_BING)){if(now)scheduleNow(js,cn,BING_NOW_JOB_ID);}else js.cancel(BING_NOW_JOB_ID);if(sources.contains(SOURCE_UNSPLASH)){if(now){android.content.SharedPreferences prefs=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);long time=System.currentTimeMillis();if(time-prefs.getLong("unsplash_now_scheduled_at",0)>=60L*60*1000){prefs.edit().putLong("unsplash_now_scheduled_at",time).apply();scheduleNow(js,cn,UNSPLASH_NOW_JOB_ID);}}}else js.cancel(UNSPLASH_NOW_JOB_ID);}
    private static void schedulePeriodic(android.app.job.JobScheduler js,android.content.ComponentName cn,int id,long period){if(js.getPendingJob(id)==null)js.schedule(new android.app.job.JobInfo.Builder(id,cn).setRequiredNetworkType(android.app.job.JobInfo.NETWORK_TYPE_UNMETERED).setPeriodic(period).setPersisted(false).build());}
    private static void scheduleNow(android.app.job.JobScheduler js,android.content.ComponentName cn,int id){js.schedule(new android.app.job.JobInfo.Builder(id,cn).setRequiredNetworkType(android.app.job.JobInfo.NETWORK_TYPE_UNMETERED).setMinimumLatency(0).setOverrideDeadline(1000).setPersisted(false).build());}
    static void refresh(Context c,int jobId)throws Exception{synchronized(MANIFEST_LOCK){if(jobId==BING_JOB_ID||jobId==BING_NOW_JOB_ID)refreshBing(c);else if(jobId==UNSPLASH_JOB_ID||jobId==UNSPLASH_NOW_JOB_ID)refreshUnsplash(c);else refreshPicsum(c);}}
    static void enforceCap(Context c){synchronized(MANIFEST_LOCK){try{write(c,list(c));}catch(Exception e){Log.e("TvHomePhotos","cap enforcement failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}}}
    private static void refreshPicsum(Context c)throws Exception{
        ensureSpace(c);File dir=dir(c);List<Photo> old=list(c);write(c,old);old=list(c);HashSet<String> existing=new HashSet<>();for(Photo p:old)if(SOURCE_PICSUM.equals(p.source))existing.add(p.id);ArrayList<Photo> incoming=new ArrayList<>();
        JSONArray items=new JSONArray(readUrl("https://picsum.photos/v2/list?page=1&limit=100",512*1024));
        for(int i=0;i<items.length()&&incoming.size()<10;i++){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");if(!hasSpace(c))break;JSONObject item=items.getJSONObject(i);String id=item.optString("id"),author=item.optString("author");if(item.optInt("width")<=item.optInt("height")||!id.matches("[0-9]+")||existing.contains(id))continue;String name="picsum_"+id+".jpg";File dst=new File(dir,name),tmp=new File(dir,name+".tmp");try{long n=download(c,"https://picsum.photos/id/"+id+"/1920/1080.jpg",tmp,FILE_CAP);if(n<=0){tmp.delete();continue;}if(dst.exists())dst.delete();if(!tmp.renameTo(dst)){tmp.delete();continue;}incoming.add(new Photo(name,id,author,SOURCE_PICSUM,"","",""));}catch(Exception e){tmp.delete();recordError(c,e);Log.e("TvHomePhotos","photo download failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));if(Thread.currentThread().isInterrupted())throw e;}}
        if(incoming.isEmpty())return;ArrayList<Photo> all=new ArrayList<>(old);all.addAll(incoming);write(c,all);
    }
    private static void refreshBing(Context c)throws Exception{
        ensureSpace(c);File dir=dir(c);List<Photo> old=list(c);write(c,old);old=list(c);ArrayList<Photo> incoming=new ArrayList<>();HashSet<String> seen=new HashSet<>();
        JSONArray images=new JSONObject(readUrl("https://www.bing.com/HPImageArchive.aspx?format=js&idx=0&n=8&mkt=en-IN",512*1024)).optJSONArray("images");if(images==null)throw new IOException("No Bing images");
        for(int i=0;i<images.length()&&incoming.size()<8;i++){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");if(!hasSpace(c))break;JSONObject item=images.getJSONObject(i);String base=item.optString("urlbase"),date=item.optString("startdate");if(base.isEmpty()||!base.matches("/[A-Za-z0-9_./?=&%-]+")||base.contains("..")||!date.matches("[0-9]{8}"))continue;if(!seen.add(base))continue;boolean exists=false;for(Photo p:old)if(SOURCE_BING.equals(p.source)&&p.id.equals(base)){exists=true;break;}if(exists)continue;String key=base.replaceAll("[^A-Za-z0-9_-]","_");String name="bing_"+key+".jpg";File dst=new File(dir,name),tmp=new File(dir,name+".tmp");try{long n=download(c,"https://www.bing.com"+base+"_1920x1080.jpg",tmp,FILE_CAP);if(n<=0){tmp.delete();continue;}if(dst.exists())dst.delete();if(!tmp.renameTo(dst)){tmp.delete();continue;}incoming.add(new Photo(name,base,"",SOURCE_BING,item.optString("title"),item.optString("copyright"),date));}catch(Exception e){tmp.delete();recordError(c,e);Log.e("TvHomePhotos","photo download failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));if(Thread.currentThread().isInterrupted())throw e;}}
        if(incoming.isEmpty())return;ArrayList<Photo> all=new ArrayList<>(old);all.addAll(incoming);all.sort((a,b)->{if(!a.source.equals(b.source))return SOURCE_BING.equals(a.source)?-1:1;return b.startdate.compareTo(a.startdate);});write(c,all);
    }
    private static void refreshUnsplash(Context c)throws Exception{
        String key=BuildConfig.UNSPLASH_ACCESS_KEY;
        if(key==null||key.trim().isEmpty()){if(!c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).getBoolean("unsplash_missing_key_logged",false)){Log.i("TvHomePhotos","Unsplash source skipped: no local API key configured");c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).edit().putBoolean("unsplash_missing_key_logged",true).apply();}return;}
        if(!reserveUnsplashCall(c))return;
        ensureSpace(c);File folder=dir(c);List<Photo> old=list(c);write(c,old);old=list(c);HashSet<String> existing=new HashSet<>();for(Photo p:old)if(SOURCE_UNSPLASH.equals(p.source))existing.add(p.id);ArrayList<Photo> incoming=new ArrayList<>();
        String endpoint="https://api.unsplash.com/photos/random?count=30&orientation=landscape&topics=nature,travel";
        String json;
        try{json=readApi(endpoint,key,1024*1024);}catch(ApiHttpException e){if(e.code<400||e.code>=500)throw e;if(!reserveUnsplashCall(c))return;json=readApi("https://api.unsplash.com/photos/random?count=30&orientation=landscape&query=nature",key,1024*1024);}
        for(UnsplashPhotoParser.Entry item:UnsplashPhotoParser.parse(json)){
            if(incoming.size()>=10)break;if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");if(!hasSpace(c)||existing.contains(item.id))continue;
            String name="unsplash_"+item.id.replaceAll("[^A-Za-z0-9_-]","_")+".jpg";File dst=new File(folder,name),tmp=new File(folder,name+".tmp");
            try{long n=0;try{n=download(c,UnsplashPhotoParser.sizedUrl(item.rawUrl),tmp,FILE_CAP);}catch(Exception primary){tmp.delete();n=download(c,item.regularUrl,tmp,FILE_CAP);}if(n<=0){tmp.delete();continue;}if(dst.exists())dst.delete();if(!tmp.renameTo(dst)){tmp.delete();continue;}try{trackUnsplashDownload(item.downloadLocation,key,0);}catch(Exception e){Log.w("TvHomePhotos","Unsplash download tracking request failed: "+e.getClass().getSimpleName());}incoming.add(new Photo(name,item.id,item.author,SOURCE_UNSPLASH,"","","",item.downloadLocation,true));existing.add(item.id);}
            catch(Exception e){tmp.delete();recordError(c,e);Log.e("TvHomePhotos","photo download failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));if(Thread.currentThread().isInterrupted())throw e;}
        }
        if(!incoming.isEmpty()){ArrayList<Photo> all=new ArrayList<>(old);all.addAll(incoming);write(c,all);}
    }
    private static boolean reserveUnsplashCall(Context c){android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);long now=System.currentTimeMillis();String stored=p.getString("unsplash_list_calls","" );ArrayList<Long> recent=new ArrayList<>();for(String value:stored.split(","))try{long at=Long.parseLong(value);if(now-at<24L*60*60*1000&&at<=now)recent.add(at);}catch(Exception ignored){}if(recent.size()>=4){Log.i("TvHomePhotos","Unsplash list request skipped: daily call limit reached");return false;}recent.add(now);StringBuilder out=new StringBuilder();for(Long at:recent){if(out.length()>0)out.append(',');out.append(at);}p.edit().putString("unsplash_list_calls",out.toString()).apply();return true;}
    private static final class ApiHttpException extends IOException{final int code;ApiHttpException(int code){super("Unsplash HTTP "+code);this.code=code;}}
    private static String readApi(String value,String key,int cap)throws Exception{return readApi(value,key,cap,0);}
    private static String readApi(String value,String key,int cap,int redirects)throws Exception{URL u=new URL(value);if(!isAllowedPhotoUrl(u)||!"api.unsplash.com".equalsIgnoreCase(u.getHost())||redirects>5)throw new IOException("URL outside Unsplash API host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("Authorization","Client-ID "+key);c.setRequestProperty("Accept-Version","v1");int code=c.getResponseCode();String remaining=c.getHeaderField("X-Ratelimit-Remaining");if(remaining!=null)Log.i("TvHomePhotos","Unsplash X-Ratelimit-Remaining="+remaining);if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("missing redirect");return readApi(new URL(u,location).toString(),key,cap,redirects+1);}if(code<200||code>=300){c.disconnect();throw new ApiHttpException(code);}try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>cap)throw new IOException("response too large");out.write(b,0,n);}return out.toString("UTF-8");}finally{c.disconnect();}}
    private static void trackUnsplashDownload(String value,String key,int redirects)throws Exception{URL u=new URL(value);if(!isAllowedPhotoUrl(u)||!"api.unsplash.com".equalsIgnoreCase(u.getHost())||redirects>5)throw new IOException("URL outside Unsplash API host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("Authorization","Client-ID "+key);c.setRequestProperty("Accept-Version","v1");int code=c.getResponseCode();String remaining=c.getHeaderField("X-Ratelimit-Remaining");if(remaining!=null)Log.i("TvHomePhotos","Unsplash X-Ratelimit-Remaining="+remaining);if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("missing redirect");trackUnsplashDownload(new URL(u,location).toString(),key,redirects+1);return;}c.disconnect();if(code<200||code>=300)throw new IOException("Unsplash tracking HTTP "+code);}
    private static ArrayList<Photo> without(List<Photo> items,String source){ArrayList<Photo> out=new ArrayList<>();for(Photo p:items)if(!source.equals(p.source))out.add(p);return out;}
    private static void write(Context c,List<Photo> photos)throws Exception{synchronized(MANIFEST_LOCK){writeLocked(c,photos);}}
    private static void writeLocked(Context c,List<Photo> photos)throws Exception{
        ArrayList<Photo> keep=new ArrayList<>(photos);long total=0;for(Photo p:keep)total+=new File(dir(c),p.file).length();
        while(total>cap(c)){Photo p=removeOldestPicsum(keep);if(p==null)p=removeOldestUnsplash(keep,dir(c));if(p==null)p=removeOldestBingBeyondNewestEight(keep);if(p==null)break;total-=new File(dir(c),p.file).length();}
        JSONArray a=new JSONArray();HashSet<String> live=new HashSet<>();for(Photo p:keep){JSONObject o=new JSONObject();o.put("file",p.file);o.put("id",p.id);o.put("author",p.author);o.put("source",p.source);o.put("title",p.title);o.put("copyright",p.copyright);o.put("startdate",p.startdate);o.put("download_location",p.downloadLocation);o.put("tracked",p.tracked);a.put(o);live.add(p.file);}JSONObject root=new JSONObject();root.put("photos",a);File manifest=new File(c.getFilesDir(),MANIFEST),temp=new File(c.getFilesDir(),MANIFEST+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}if(manifest.exists())manifest.delete();if(!temp.renameTo(manifest))throw new IOException("Could not replace photo manifest");File[] files=dir(c).listFiles();if(files!=null)for(File f:files)if(f.isFile()&&f.getName().endsWith(".jpg")&&!live.contains(f.getName()))f.delete();
    }
    private static Photo removeOldestPicsum(List<Photo> all){for(int i=0;i<all.size();i++)if(SOURCE_PICSUM.equals(all.get(i).source))return all.remove(i);return null;}
    private static Photo removeOldestUnsplash(List<Photo> all,File folder){Photo oldest=null;long time=Long.MAX_VALUE;for(Photo p:all)if(SOURCE_UNSPLASH.equals(p.source)){long candidate=new File(folder,p.file).lastModified();if(candidate<time){oldest=p;time=candidate;}}if(oldest!=null)all.remove(oldest);return oldest;}
    private static Photo removeOldestBingBeyondNewestEight(List<Photo> all){ArrayList<Photo> bing=new ArrayList<>();for(Photo p:all)if(SOURCE_BING.equals(p.source))bing.add(p);bing.sort((a,b)->b.startdate.compareTo(a.startdate));if(bing.size()<=8)return null;Photo p=bing.get(bing.size()-1);all.remove(p);return p;}
    private static boolean hasSpace(Context c){return new StatFs(c.getFilesDir().getAbsolutePath()).getAvailableBytes()>=MIN_FREE;}
    private static void ensureSpace(Context c)throws IOException{if(!hasSpace(c))throw new IOException("Insufficient data partition space for photo download");}
    private static long download(Context c,String url,File out,long cap)throws Exception{ensureSpace(c);try(InputStream in=open(url,0);FileOutputStream dst=new FileOutputStream(out)){byte[] b=new byte[16384];long n=0;int r;while((r=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");ensureSpace(c);n+=r;if(n>cap)throw new IOException("photo over 1.5 MB");dst.write(b,0,r);ensureSpace(c);}return n;}}
    private static String readUrl(String url,int cap)throws Exception{try(InputStream in=open(url,0);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int r,n=0;while((r=in.read(b))!=-1){n+=r;if(n>cap)throw new IOException("response too large");out.write(b,0,r);}return out.toString("UTF-8");}}
    static boolean isAllowedPhotoUrl(URL u){return PhotoUrlPolicy.isAllowed(u);}
    private static InputStream open(String value,int redirects)throws Exception{URL u=new URL(value);if(!PhotoUrlPolicy.isAllowed(u)||redirects>5)throw new IOException("URL outside photo hosts");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","CleanYourTV/2.10");int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("missing redirect");return open(new URL(u,location).toString(),redirects+1);}if(code<200||code>=300){c.disconnect();throw new IOException("Photo HTTP "+code);}return new DisconnectingInputStream(c);}
    private static String readText(File f)throws Exception{return new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8);}
    private static final class DisconnectingInputStream extends FilterInputStream{final HttpURLConnection c;DisconnectingInputStream(HttpURLConnection c)throws Exception{super(c.getInputStream());this.c=c;}public void close()throws IOException{try{super.close();}finally{c.disconnect();}}}
}
